INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Privacy by Default ein freiwilliges Prinzip?', 2, '[{"text": "Nein", "correct": true, "because": "In der DSGVO verpflichtend"}, {"text": "Ja", "correct": false, "because": "Gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel von Privacy by Default?', 3, '[{"text": "Minimierung der Datenerfassung", "correct": true, "because": "Nur notwendige Daten standardmäßig"}, {"text": "Maximale Datenspeicherung", "correct": false, "because": "Gegenteil des Prinzips"}, {"text": "Manuelle Einstellungen", "correct": false, "because": "Automatisch geschützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen gehören zu Privacy by Default?', 5, '[{"text": "Standardmäßige Datensparsamkeit", "correct": true, "because": "Nur erforderliche Daten"}, {"text": "Deaktivierte Tracking-Funktionen", "correct": true, "because": "Schützt Nutzerdaten"}, {"text": "Automatische Datenfreigabe", "correct": false, "because": "Widerspricht Prinzip"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Privacy by Default ist Teil der DSGVO. b) Es erfordert immer Nutzerzustimmung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist bei Standardeinstellungen nicht nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Umsetzung von Privacy by Default?', 4, '[{"text": "Datenschutzeinstellungen", "correct": false, "because": "Kern des Prinzips"}, {"text": "Nutzerrechte", "correct": false, "because": "Müssen geschützt werden"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant für Datenschutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Privacy by Default die Zustimmung für alle Datenverarbeitungen erfordert?', 2, '[{"text": "Nein", "correct": true, "because": "Datenschutz ist Standard, Zustimmung optional"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend für Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip ergänzt Privacy by Default?', 3, '[{"text": "Privacy by Design", "correct": true, "because": "Datenschutz von Anfang an"}, {"text": "Maximale Datenerfassung", "correct": false, "because": "Widerspricht Prinzip"}, {"text": "Manuelle Konfiguration", "correct": false, "because": "Automatisierung bevorzugt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind bei Privacy by Default wichtig?', 5, '[{"text": "Standardmäßiger Datenschutz", "correct": true, "because": "Minimale Datenerfassung"}, {"text": "Transparente Einstellungen", "correct": true, "because": "Nutzer informieren"}, {"text": "Offene Datenfreigabe", "correct": false, "because": "Gegen Prinzip"}, {"text": "Hohe Grafikleistung", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Privacy by Default schützt Nutzerdaten automatisch. b) Es erlaubt alle Datenverarbeitungen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) schränkt Verarbeitung ein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Privacy by Default?', 4, '[{"text": "Datenschutzvoreinstellungen", "correct": false, "because": "Kern des Prinzips"}, {"text": "DSGVO-Konformität", "correct": false, "because": "Gesetzlich erforderlich"}, {"text": "3D-Animationen", "correct": true, "because": "Irrelevant für Datenschutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Gilt Privacy by Default nur für neue Systeme?', 2, '[{"text": "Nein", "correct": true, "because": "Auch bestehende Systeme betroffen"}, {"text": "Ja", "correct": false, "because": "Alle Systeme eingeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einstellungen sind typisch für Privacy by Default?', 4, '[{"text": "Deaktivierte Datenfreigabe", "correct": true, "because": "Schützt standardmäßig"}, {"text": "Minimierte Datenerfassung", "correct": true, "because": "Nur notwendige Daten"}, {"text": "Aktivierte Cookies", "correct": false, "because": "Widerspricht Prinzip"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Privacy by Default die Nutzerfreundlichkeit senkt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Schutz ohne Komplexität"}, {"text": "Ja", "correct": false, "because": "Einfachheit erhalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Privacy by Default?', 3, '[{"text": "Datensparsamkeit", "correct": true, "because": "Nur notwendige Daten erfassen"}, {"text": "Maximale Datenspeicherung", "correct": false, "because": "Gegen Prinzip"}, {"text": "Manuelle Anpassung", "correct": false, "because": "Automatisierung wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Privacy by Default reduziert Datenrisiken. b) Es erfordert immer externe Audits.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Privacy by Default?', 5, '[{"text": "Erhöhte Nutzersicherheit", "correct": true, "because": "Schützt automatisch"}, {"text": "DSGVO-Konformität", "correct": true, "because": "Erfüllt Vorgaben"}, {"text": "Hohe Komplexität", "correct": false, "because": "Eher Nachteil"}, {"text": "Maximale Datenerfassung", "correct": false, "because": "Gegen Prinzip"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Privacy by Default unwichtig?', 3, '[{"text": "Standardkonfiguration", "correct": false, "because": "Kern des Prinzips"}, {"text": "Nutzerinformation", "correct": false, "because": "Fördert Transparenz"}, {"text": "Musikwiedergabe", "correct": true, "because": "Kein Datenschutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Privacy by Default für alle Daten gilt?', 2, '[{"text": "Ja", "correct": true, "because": "Alle personenbezogenen Daten betroffen"}, {"text": "Nein", "correct": false, "because": "Umfassend anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss der Nutzer bei Privacy by Default aktiv zustimmen?', 3, '[{"text": "Nein", "correct": true, "because": "Schutz ist Standardeinstellung"}, {"text": "Ja", "correct": false, "because": "Zustimmung optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu Privacy by Default?', 4, '[{"text": "App mit deaktiviertem Tracking", "correct": true, "because": "Schützt Nutzerdaten standardmäßig"}, {"text": "Netzwerkkonfiguration", "correct": false, "because": "Technische Aufgabe"}, {"text": "Musikwiedergabe", "correct": false, "because": "Kein Datenschutzfokus"}]');
